    "How well it worked in epoch {n}": { ru: "Как он работал в эпохе {n}", zh: "在 epoch {n} 中的表现", hi: "एपॉक {n} में इसने कितना अच्छा काम किया", es: "Qué tal funcionó en la época {n}", ar: "مدى جودة عملها في الحقبة {n}", fr: "Comment il a fonctionné à l'époque {n}", pt: "Como funcionou na época {n}", de: "Wie gut er in Epoche {n} gearbeitet hat", it: "Come ha funzionato nell'epoca {n}", pl: "Jak działał w epoce {n}" },
    "Requests answered": { ru: "Отвеченные запросы", zh: "已响应的请求", hi: "जवाब दिए गए अनुरोध", es: "Solicitudes respondidas", ar: "الطلبات المُجاب عنها", fr: "Requêtes traitées", pt: "Solicitações respondidas", de: "Beantwortete Anfragen", it: "Richieste evase", pl: "Obsłużone żądania" },
